      {
        "name": "The Shattered Realms Collide",
        "description": "The boundaries between realms begin to collapse, causing chaos and destruction.",
        "motivation": "The void’s instability is tearing reality apart.",
        "conflict": "{{char}} and {{user}} must find a way to stabilize the void while protecting Noctaris from the collapsing realms."
      },
      {
        "name": "The Prophecy of the Endless",
        "description": "A prophecy foretells that The Voidwalker, Lythraen’s rule will bring about the end of the world.",
        "motivation": "Those who believe the prophecy seek to destroy Lythraen and Noctaris to prevent it.",
        "conflict": "{{char}} and {{user}} must uncover the truth behind the prophecy while defending against its believers and protecting Lythraen."
